package com.buildertoolbox.client.utils.player; import net.minecraft.client.MinecraftClient; import net.minecraft.item.Item; import net.minecraft.screen.slot.SlotActionType; public final class InvUtils {public static FindItemResult find(Item item){var mc=MinecraftClient.getInstance();if(mc.player!=null)for(int i=0;i<36;i++){var s=mc.player.getInventory().getStack(i);if(s.isOf(item))return new FindItemResult(i,s.getCount());}return new FindItemResult(-1,0);} public static void swap(int slot,boolean back){var p=MinecraftClient.getInstance().player;if(p!=null&&slot>=0&&slot<9)p.getInventory().setSelectedSlot(slot);} public static Click shiftClick(){return new Click();} public static final class Click {public void slotId(int slot){var mc=MinecraftClient.getInstance();if(mc.player!=null&&mc.interactionManager!=null)mc.interactionManager.clickSlot(mc.player.currentScreenHandler.syncId,slot,0,SlotActionType.QUICK_MOVE,mc.player);}} }